import * as T from './vendor/three.module.js';
import {panelPorts,panelOutline,panelHoles} from './classic-panels.js';
export function panelGeometry(d,mat){const g=new T.Group(),outline=panelOutline(d),s=new T.Shape(outline.map(p=>new T.Vector2(...p)));s.closePath();for(const [x,y]of panelHoles(d)){const hole=new T.Path();hole.absarc(x,y,3.1,0,Math.PI*2,true);s.holes.push(hole);}const geo=new T.ExtrudeGeometry(s,{depth:1.65,bevelEnabled:false,curveSegments:12});geo.translate(0,0,-.825);const face=new T.Mesh(geo,mat);face.castShadow=face.receiveShadow=true;g.add(face);
 const add=(geo,pos,quat)=>{const m=new T.Mesh(geo,mat);m.position.fromArray(pos);if(quat)m.quaternion.copy(quat);m.castShadow=m.receiveShadow=true;g.add(m);};
 for(let i=0;i<outline.length;i++){const a=new T.Vector3(...outline[i],0),b=new T.Vector3(...outline[(i+1)%outline.length],0),dir=b.clone().sub(a),mid=a.clone().add(b).multiplyScalar(.5);add(new T.CylinderGeometry(.65,.65,dir.length(),8),mid.toArray(),new T.Quaternion().setFromUnitVectors(new T.Vector3(0,1,0),dir.normalize()));}
 for(const port of panelPorts(d)){const dir=new T.Vector3(...port.dir),tip=new T.Vector3(...port.pos),q=new T.Quaternion().setFromUnitVectors(new T.Vector3(0,1,0),dir);for(const [back,length,r]of[[5.5,11,2.15],[1.05,2.1,3.05],[6.6,1.1,2.95]])add(new T.CylinderGeometry(r,r,length,16),tip.clone().addScaledVector(dir,-back).toArray(),q);}return g;}
export function panelIcon(d){const poly=panelOutline(d),ports=panelPorts(d),extent=Math.max(d.pitch,2*d.reach),scale=80/extent;return `<svg viewBox="0 0 120 58" aria-hidden="true"><g transform="translate(60 29) scale(${Math.min(scale,45/(d.panelShape==='square'?d.pitch:d.reach))})"><path d="M${poly.map(([x,y])=>x+','+-y).join('L')}Z" fill="${d.color}" stroke="#87958c" stroke-width="1.5"/>${panelHoles(d).map(([x,y])=>`<circle cx="${x}" cy="${-y}" r="3.1" fill="#202833"/>`).join('')}${ports.map(p=>`<path d="M${p.pos[0]},${-p.pos[1]}l${-p.dir[0]*9},${p.dir[1]*9}" stroke="${d.color}" stroke-width="5" stroke-linecap="round"/>`).join('')}</g></svg>`;}
